theorem vanishing_criterion (p : ℕ) [Fact (Nat.Prime p)] (h_odd : p % 2 = 1) (a : ZMod p) (ha : a ≠ 0) :
    let n := (p - 1) / 2
    let χ := fun k : ZMod p => (ZMod.legendreSymbol p k : ℤ)
    let M := Matrix.of fun (i j : Fin n) => χ (↑i * ↑i - a * ↑j)
    M.det = 0 ↔ p % 4 = 3 ∧ χ (a * ↑(Nat.factorial n)) = 1 := by sorry

theorem dichotomy_count_rank_bounds {M M' n : ℕ} {E : Set (Fin n → ℝ)} (hE : E.Finite) (Φ : (Fin n → ℝ) → Fin M' → ℝ) (r s : ℕ) (hr : r = FiniteField.rank (Fin.map Φ ∘ Subtype.val '' E)) (hs : s = kruskal_rank (Fin.map Φ ∘ Subtype.val '' E)) (hs_le : s ≤ r) : cover_count s n ≤ dichotomy_count Φ E ∧ dichotomy_count Φ E ≤ cover_count r n := by
  sorry

def cover_count (d n : ℕ) : ℕ := 2 * (Finset.range (min d n)).sum (fun k => Nat.choose (n - 1) k)

def kruskal_rank {m n : ℕ} (v : Fin m → Fin n → ℝ) : ℕ := Finset.sup (Finset.range m) (fun s => if ∀ (S : Finset (Fin m)), S.card = s + 1 → LinearIndependent ℝ (fun i => v i) then s + 1 else 0)

theorem cyclotomic_gauss_matrix_factorization
    {N : ℕ} {p m k : ℕ} {χ : (ZMod N)ˣ →* Circle} (g : (ZMod N)ˣ)
    (hN : N = p ^ m) (hk : k ∣ Nat.totient N) (hχ : IsGenerator χ) :
    let n := (Nat.totient N) / k
    let ω := χ ^ k g
    let A := Matrix.of fun i j : Fin n => gaussSum N (χ ^ (k * (i : ℕ) + k * (j : ℕ)))
    let W := Matrix.of fun i a : Fin n => ω ^ ((a : ℕ) * (i : ℕ))
    let D := Matrix.diagonal (fun a : Fin n => gaussPeriod N k a)
    A = W * D * W.transpose :=
  sorry

theorem sprung_lambda_invariant_difference_formula
  (E : EllipticCurve ℚ) (hE_ss : SupersingularReduction E 2) (hE_sf : Squarefree (conductor E))
  (D : ℤ) (hD_sf : Squarefree D) (hD_pos : 0 < D) (hD_mod : D % 4 = 1)
  (star : SharpFlat) (i : Fin 2) (h_mu_zero : mu_invariant E star i = 0) :
  lambda_invariant (quadratic_twist E D) star i = lambda_invariant E star i +
    (prime_divisors D).sum fun ell =>
      if (ell : ℤ) ∣ conductor E then 2^(padicVal 2 ((ell^2 - 1) / 8))
      else if 2 ∣ (E.reduce ell).card then 2^(padicVal 2 ((ell^2 - 1) / 8) + 1)
      else 0 :=
by sorry

directions.description:
We conjecture that for every uniformity r≥2 the extremal \u03c7₀^r_F(d) (the maximum minimum number of colors needed for an \u03c6‑coloring of an r‑uniform hypergraph of maximum degree d, where \u03c6 is the family consisting of all balanced triangles as defined in the paper) satisfies the tight asymptotic bound

    C1 · (d^3/ln d)^{1/(3r‑4)} ≤ χ^r_F(d) ≤ C2 · (d^3/ln d)^{1/(3r‑4)}

for all sufficiently large d and some absolute constants C1, C2 > 0.  In particular the lower bound proved in the paper is optimal up to constant factors.

